// Overview page: KPI tiles, collection priorities, upcoming conversations. Runs on records/masters onDataQuerySuccess and the Overview page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const rows = queries.records.data || [], customers = queries.masters.data || [];
const money = n => '$' + (n / 100).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const usd = n => n.toLocaleString('en-US', {style: 'currency', currency: 'USD'});
const bal = x => x.amount_cents - (x.payments || []).reduce((n, p) => n + p.cents, 0);
const today = new Date().toLocaleDateString('en-CA');
const age = x => Math.max(0, Math.floor((new Date(today + 'T12:00:00') - new Date(x.due + 'T12:00:00')) / 86400000));
const dateLong = d => d ? new Date(d + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric', year: 'numeric'}) : 'Not scheduled';
const dateShort = d => d ? new Date(d + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'Not scheduled';
const open = rows.filter(r => r.status === 'Open');
const sum = list => list.reduce((n, r) => n + bal(r) / 100, 0);
const collections = open.slice().sort((a, b) => a.due.localeCompare(b.due)).slice(0, 4).map(x => ({
  id: x.id, customer: e(x.customer), invoice: e(x.name), balance: money(bal(x)), paid: money(x.amount_cents - bal(x)) + ' recorded paid',
  statusText: age(x) ? age(x) + ' days overdue' : 'Current', statusColor: age(x) ? 'var(--cc-warning-systemStatus)' : 'var(--cc-success-systemStatus)',
  due: 'Due ' + dateLong(x.due), next: dateLong(x.followup), owner: e(x.owner)
}));
const promises = open.filter(x => x.followup).sort((a, b) => a.followup.localeCompare(b.followup)).slice(0, 2).map(x => ({ empty: false, line1: dateShort(x.followup) + ' · ' + x.customer, line2: x.owner + ' · ' + money(bal(x)) + ' remaining' }));
return {
  outstanding: usd(sum(open)),
  overdue: usd(sum(open.filter(r => r.due < today))),
  openCount: String(open.length),
  customers: String(customers.length),
  collections,
  promises: promises.length ? promises : [{ empty: true, line1: 'Log a follow-up to schedule the next conversation.', line2: '' }]
};

// Invoice workspace: selected invoice summary + history. Runs on records.onDataQuerySuccess and the page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const r = (queries.records.data || []).find(x => x.id === variables.recordId);
const money = n => '$' + (n / 100).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const dateLong = d => d ? new Date(d + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric', year: 'numeric'}) : 'Not scheduled';
const bal = x => x.amount_cents - (x.payments || []).reduce((n, p) => n + p.cents, 0);
const history = (r?.history || []).slice().reverse().map(h => ({ event: e(h.event), at: e(String(h.at || '').slice(0, 16).replace('T', ' ')), note: h.note || '' }));
if (!r) return { has: false, name: '', customer: '', meta: '', balance: '', received: '', history: [{ event: '', at: 'Select a record to inspect its saved activity.', note: '' }] };
return {
  has: true,
  name: e(r.name),
  customer: r.customer,
  meta: r.owner + ' · Due ' + dateLong(r.due) + ' · ' + r.status,
  balance: money(bal(r)),
  received: money(r.amount_cents - bal(r)) + ' received of ' + money(r.amount_cents),
  history
};
